fn first_even_odd_indices(lst: Vec<i32>) -> (usize, usize) {
    // Find the first even element index: i
    let i = lst.iter()
        .position(|&x| x % 2 == 0)
        .expect("The list must contain at least one even number");

    // Find the first odd element index: j
    let j = lst.iter()
        .position(|&x| x % 2 != 0)
        .expect("The list must contain at least one odd number");

    (i, j)
}